insert into public.products (slug, name, brand, model, reference, description, price, currency, image, stock)
values
  ('casio-edifice-efb-730d-3av', 'Casio Edifice Sapphire Kronograf', 'Casio', 'Edifice Sapphire Kronograf', 'EFB-730D-3AV', 'Açık yeşil kadranın üzerinde koyu alt kadranlar: klasik yarış kronograflarından ilham alan 3-6-9 düzeni, safir cam ve çelik bilezik. Edifice serisinin en zarif kronograflarından biri.', 14950.00, 'TRY', '/assets/images/watches/front/x-casio-edifice-efb-730d-3av.webp', 1),
  ('casio-edifice-efr-s108de-3av', 'Casio Edifice Slim Sapphire', 'Casio', 'Edifice Slim Sapphire', 'EFR-S108DE-3AV', '7,8 mm inceliğinde kasa, saç teli işlemeli sekizgen çerçeve ve dokulu yeşil kadran. Safir camıyla Edifice''in en rafine üç ibreli modellerinden biri.', 12450.00, 'TRY', '/assets/images/watches/front/x-casio-edifice-efr-s108de-3av.webp', 1),
  ('casio-mtp-e515d-2a2', 'Casio Kronograf — Yeşil Kadran', 'Casio', 'Kronograf — Yeşil Kadran', 'MTP-E515D-2A2', 'Derin yeşil kadran, 24 saat ve kronometre alt kadranları, tarih penceresi ve karanlıkta parlayan ibreler. Günlük kullanım için sportif ve okunaklı bir kronograf.', 4850.00, 'TRY', '/assets/images/watches/front/x-casio-mtp-e515d-2a2.webp', 1),
  ('casio-mtp-1374d-5av', 'Casio Multifonksiyon — Kırmızı Çerçeve', 'Casio', 'Multifonksiyon — Kırmızı Çerçeve', 'MTP-1374D-5AV', 'Siyah kadranı saran bordo çerçeve; gün, tarih ve 24 saat alt kadranları, parlayan ibre ve indeksler. Sportif karakterli, güçlü bir günlük saat.', 6250.00, 'TRY', '/assets/images/watches/front/x-casio-mtp-1374d-5av.webp', 1),
  ('casio-la680wga-4c', 'Casio Vintage Mini — Altın, Çiçek Desenli', 'Casio', 'Vintage Mini — Altın, Çiçek Desenli', 'LA680WGA-4C', 'Altın tonlu retro kasa ve kadranın köşesinde pembe çiçek motifleri. LED ışık, alarm, kronometre ve takvimiyle Casio Vintage serisinin en sevilen kadın modellerinden.', 3650.00, 'TRY', '/assets/images/watches/front/x-casio-la680wga-4c.webp', 1),
  ('casio-a700w-1a', 'Casio Vintage İnce Dijital', 'Casio', 'Vintage İnce Dijital', 'A700W-1A', 'Yaklaşık 6 mm inceliğinde kasa, siyah çerçeveli ekran ve çelik bilezik. Alarm, 1/100 saniye kronometre, takvim ve LED ışık; retro Casio çizgisinin en ince yorumu.', 2950.00, 'TRY', '/assets/images/watches/front/x-casio-a700w-1a.webp', 1),
  ('casio-f-91w-gumus-metal', 'Casio F-91W — Gümüş Metal', 'Casio', 'F-91W — Gümüş Metal', 'F-91W', '1989''dan beri neredeyse hiç değişmeyen efsanevi F-91W, gümüş tonlu kasa ve çelik bilezikle. Alarm, kronometre ve LED ışık.', 1950.00, 'TRY', '/assets/images/watches/front/x-casio-f-91w-gumus-metal.webp', 1),
  ('casio-f-91ws-2', 'Casio F-91W — Şeffaf Mavi', 'Casio', 'F-91W — Şeffaf Mavi', 'F-91WS-2', 'Efsanevi F-91W''nun şeffaf mavi reçine kasa ve kayışlı hali. Alarm, kronometre, LED ışık ve yaklaşık 7 yıllık pil ömrü.', 1750.00, 'TRY', '/assets/images/watches/front/x-casio-f-91ws-2.webp', 1),
  ('casio-ltp-v009g-7e', 'Casio Dikdörtgen — Altın, Beyaz Kadran', 'Casio', 'Dikdörtgen — Altın, Beyaz Kadran', 'LTP-V009G-7E', 'Altın renk kaplama dikdörtgen kasa, sade beyaz kadran ve ince çubuk indeksler. Zarif ve hafif bir günlük kadın saati.', 2450.00, 'TRY', '/assets/images/watches/front/x-casio-ltp-v009g-7e.webp', 1),
  ('casio-ltp-1275sg-7b', 'Casio Klasik — Bicolor, Beyaz Kadran', 'Casio', 'Klasik — Bicolor, Beyaz Kadran', 'LTP-1275SG-7B', 'Gümüş ve altın tonlarının birleştiği bilezik, okunaklı Arap rakamlı beyaz kadran. Zamansız ve kolay kombinlenen bir kadın saati.', 2950.00, 'TRY', '/assets/images/watches/front/x-casio-ltp-1275sg-7b.webp', 1),
  ('daniel-klein-exclusive-siyah-deri', 'Daniel Klein Exclusive — Siyah, Deri Kayış', 'Daniel Klein', 'Exclusive — Siyah, Deri Kayış', '', 'Siyah kaplama kasa, dokulu siyah kadran ve gün göstergeli alt kadranlar. Turuncu detaylı kurma kolu ve siyah deri kayışla güçlü bir akşam saati.', 3450.00, 'TRY', '/assets/images/watches/front/x-daniel-klein-exclusive-siyah-deri.webp', 1),
  ('daniel-klein-yesil-kadran-bicolor', 'Daniel Klein Klasik — Yeşil Kadran, Bicolor', 'Daniel Klein', 'Klasik — Yeşil Kadran, Bicolor', '', 'Güneş ışını efektli yeşil kadran, altın çerçeve ve tarih penceresi. Gümüş-altın bicolor bilezikle şık ve klasik bir erkek saati.', 3950.00, 'TRY', '/assets/images/watches/front/x-daniel-klein-yesil-kadran-bicolor.webp', 1),
  ('daniel-klein-exclusive-yesil-altin', 'Daniel Klein Exclusive — Yeşil Kadran, Altın Kasa', 'Daniel Klein', 'Exclusive — Yeşil Kadran, Altın Kasa', '', 'Altın tonlu kasa, yeşil kadran ve altın çerçeveli alt kadranlar; gün ve tarih göstergeleriyle. Kahverengi deri kayış klasik bir tamamlayıcı.', 4950.00, 'TRY', '/assets/images/watches/front/x-daniel-klein-exclusive-yesil-altin.webp', 1),
  ('daniel-klein-exclusive-pembe-kadran', 'Daniel Klein Exclusive — Pudra Kadran, Siyah Alt Kadranlar', 'Daniel Klein', 'Exclusive — Pudra Kadran, Siyah Alt Kadranlar', '', 'Kum dokulu pudra pembesi kadranın üzerinde siyah alt kadranlar ve tarih. Köşeli kasa ve entegre görünümlü çelik bilezik.', 4650.00, 'TRY', '/assets/images/watches/front/x-daniel-klein-exclusive-pembe-kadran.webp', 1),
  ('daniel-klein-exclusive-siyah-celik', 'Daniel Klein Exclusive — Siyah Çelik', 'Daniel Klein', 'Exclusive — Siyah Çelik', '', 'Baştan sona siyah: siyah kaplama kasa ve bilezik, siyah kadran, gün ve tarih göstergeleri. Parlayan beyaz indekslerle okunaklı ve iddialı.', 4450.00, 'TRY', '/assets/images/watches/front/x-daniel-klein-exclusive-siyah-celik.webp', 1),
  ('daniel-klein-gun-tarih-tirtikli', 'Daniel Klein Gün-Tarih — Tırtıklı Çerçeve', 'Daniel Klein', 'Gün-Tarih — Tırtıklı Çerçeve', '', 'Tırtıklı çerçeve, gün adını tam yazan pencere, büyüteçli tarih ve beş sıralı bilezik. Klasik bir elbise saatinin kolay ulaşılır yorumu.', 3750.00, 'TRY', '/assets/images/watches/front/x-daniel-klein-gun-tarih-tirtikli.webp', 1),
  ('daniel-klein-exclusive-yesil-siyah', 'Daniel Klein Exclusive — Siyah Kasa, Yeşil Kadran', 'Daniel Klein', 'Exclusive — Siyah Kasa, Yeşil Kadran', '', 'Siyah kasanın içinde güneş ışını efektli koyu yeşil kadran, bakır tonlu detaylar ve tarih. Köşeli hatlarla sportif ve modern.', 4850.00, 'TRY', '/assets/images/watches/front/x-daniel-klein-exclusive-yesil-siyah.webp', 1),
  ('daniel-klein-exclusive-gumus-kadran', 'Daniel Klein Exclusive — Gümüş Kadran, Köşeli Kasa', 'Daniel Klein', 'Exclusive — Gümüş Kadran, Köşeli Kasa', '', 'Gümüş kadran, mavi vurgulu alt kadranlar, gün ve tarih göstergeleri. Vida detaylı köşeli kasa ve çelik bilezikle sportif bir görünüm.', 4350.00, 'TRY', '/assets/images/watches/front/x-daniel-klein-exclusive-gumus-kadran.webp', 1),
  ('daniel-klein-exclusive-beyaz-cizgili', 'Daniel Klein Exclusive — Beyaz Yatay Çizgili Kadran', 'Daniel Klein', 'Exclusive — Beyaz Yatay Çizgili Kadran', '', 'Yuvarlatılmış köşeli kasa, yatay çizgili beyaz kadran, alt kadranlar ve tarih. Entegre görünümlü çelik bilezikle sade ve modern bir spor şıklığı.', 5250.00, 'TRY', '/assets/images/watches/front/x-daniel-klein-exclusive-beyaz-cizgili.webp', 1),
  ('essence-kare-yesil-roma', 'Essence Kare — Yeşil Kadran, Roma Rakamları', 'Essence', 'Kare — Yeşil Kadran, Roma Rakamları', '', 'Altın tonlu kare kasa, derin yeşil kadran ve Roma rakamları. Boncuk dizisi gibi işlenmiş bilezikle mücevher etkisi veren bir kadın saati.', 4250.00, 'TRY', '/assets/images/watches/front/x-essence-kare-yesil-roma.webp', 1),
  ('essence-kare-sedef-tasli-bilezik', 'Essence Kare — Sedef Kadran, Taşlı Bilezik', 'Essence', 'Kare — Sedef Kadran, Taşlı Bilezik', '', 'Geniş altın kasa, taş indeksli sedef kadran ve sıra sıra kristal taşlarla bezeli geniş bilezik. Gece için tasarlanmış bir mücevher saat.', 4650.00, 'TRY', '/assets/images/watches/front/x-essence-kare-sedef-tasli-bilezik.webp', 1),
  ('essence-sekizgen-sedef-zincir', 'Essence Sekizgen — Sedef Kadran, Zincir Bilezik', 'Essence', 'Sekizgen — Sedef Kadran, Zincir Bilezik', '', 'Fasetalı camın altında sedef kadran, taşlı sekizgen çerçeve ve kalın zincir bilezik. Klasik bir formun cesur ve modern yorumu.', 3950.00, 'TRY', '/assets/images/watches/front/x-essence-sekizgen-sedef-zincir.webp', 1),
  ('essence-sedef-tasli-bicolor-rose', 'Essence Sedef Kadran — Taşlı Çerçeve, Rose Bicolor', 'Essence', 'Sedef Kadran — Taşlı Çerçeve, Rose Bicolor', '', 'Sekizgen hatlı çerçevede çift sıra taş, rose altın detaylı sedef kadran. Gümüş ve rose altın bicolor bilezik.', 4450.00, 'TRY', '/assets/images/watches/front/x-essence-sedef-tasli-bicolor-rose.webp', 1),
  ('essence-multifonksiyon-altin', 'Essence Multifonksiyon — Altın, Tırtıklı Çerçeve', 'Essence', 'Multifonksiyon — Altın, Tırtıklı Çerçeve', '', 'Tırtıklı altın çerçeve, Roma rakamlı sedef kadran ve üç alt kadran. Altın bilezikle klasik ve güçlü bir kadın saati.', 5450.00, 'TRY', '/assets/images/watches/front/x-essence-multifonksiyon-altin.webp', 1),
  ('essence-yesil-kadran-tasli', 'Essence Yeşil Kadran — Taşlı Çerçeve', 'Essence', 'Yeşil Kadran — Taşlı Çerçeve', '', 'Yeşil sedef efektli kadranı saran kristal taşlı çerçeve ve sade altın indeksler. Altın bilezikle göz alıcı bir renk dengesi.', 4250.00, 'TRY', '/assets/images/watches/front/x-essence-yesil-kadran-tasli.webp', 1),
  ('essence-dikdortgen-sedef-bicolor', 'Essence Dikdörtgen — Sedef Kadran, Bicolor', 'Essence', 'Dikdörtgen — Sedef Kadran, Bicolor', '', 'Altın kenarlı dikdörtgen kasa, Arap rakamlı sedef kadran ve bicolor bilezik. Zamansız, gündüzden akşama uyum sağlayan bir model.', 3850.00, 'TRY', '/assets/images/watches/front/x-essence-dikdortgen-sedef-bicolor.webp', 1),
  ('essence-mini-sedef-rose', 'Essence Mini — Sedef Kadran, Rose Bicolor', 'Essence', 'Mini — Sedef Kadran, Rose Bicolor', '', 'Küçük yuvarlak kasa, taşlı çerçeve ve sedef kadran; gümüş ve rose altın bilezik. İnce bileklere zarif bir dokunuş.', 3450.00, 'TRY', '/assets/images/watches/front/x-essence-mini-sedef-rose.webp', 1),
  ('freelook-baget-tasli-yesil', 'Freelook Baget Taşlı — Yeşil Kadran, Bicolor', 'Freelook', 'Baget Taşlı — Yeşil Kadran, Bicolor', '', 'Baget kesim taşlarla çevrili yeşil kadran ve gümüş-altın bicolor bilezik. Freelook''un ışıltılı Paris çizgisinin en dikkat çeken modellerinden.', 7950.00, 'TRY', '/assets/images/watches/front/x-freelook-baget-tasli-yesil.webp', 1),
  ('freelook-yesil-kadran-tasli', 'Freelook Yeşil Kadran — Taşlı Çerçeve', 'Freelook', 'Yeşil Kadran — Taşlı Çerçeve', '', 'Güneş ışını efektli yeşil kadran, taşlı çerçeve ve baget taşlı kulp detayları. Bicolor bilezikle canlı ve zarif.', 6950.00, 'TRY', '/assets/images/watches/front/x-freelook-yesil-kadran-tasli.webp', 1),
  ('freelook-diamond-sedef', 'Freelook Diamond — Sedef Kadran, Taşlı Bilezik', 'Freelook', 'Diamond — Sedef Kadran, Taşlı Bilezik', '', 'Taşlı çerçeveli küçük yuvarlak kasa, sedef kadran ve tek sıra taşlı ince bilezik. Bir bileklik kadar narin bir saat.', 7450.00, 'TRY', '/assets/images/watches/front/x-freelook-diamond-sedef.webp', 1),
  ('freelook-multifonksiyon-leopar', 'Freelook Multifonksiyon — Altın, Desenli Kadran', 'Freelook', 'Multifonksiyon — Altın, Desenli Kadran', '', 'Taşlı altın çerçeve, siyah ve altın desenli kadran, gün ve tarih alt kadranları. İddialı ve ışıltılı bir kadın saati.', 8950.00, 'TRY', '/assets/images/watches/front/x-freelook-multifonksiyon-leopar.webp', 1),
  ('freelook-roma-rakamli-bicolor', 'Freelook Roma Rakamları — Taş İndeksli, Bicolor', 'Freelook', 'Roma Rakamları — Taş İndeksli, Bicolor', '', 'Dokulu gümüş kadranda Roma rakamları ve taş indeksler; vida detaylı çerçeve ve bicolor bilezik.', 6450.00, 'TRY', '/assets/images/watches/front/x-freelook-roma-rakamli-bicolor.webp', 1),
  ('freelook-kare-gumus-tasli', 'Freelook Kare — Gümüş Kadran, Taşlı Çerçeve', 'Freelook', 'Kare — Gümüş Kadran, Taşlı Çerçeve', '', 'Taşlarla çevrili kare kasa, güneş ışını efektli gümüş kadran ve bicolor bilezik. Modern ve sade bir mücevher saat.', 6250.00, 'TRY', '/assets/images/watches/front/x-freelook-kare-gumus-tasli.webp', 1),
  ('freelook-dikdortgen-beyaz-altin', 'Freelook Dikdörtgen — Beyaz Kadran, Altın', 'Freelook', 'Dikdörtgen — Beyaz Kadran, Altın', '', 'Altın tonlu dikdörtgen kasa, Roma rakamlı beyaz kadran ve altın bilezik. Klasik bir tank formunun zarif yorumu.', 6750.00, 'TRY', '/assets/images/watches/front/x-freelook-dikdortgen-beyaz-altin.webp', 1),
  ('freelook-klasik-beyaz-altin', 'Freelook Klasik — Desenli Beyaz Kadran, Altın', 'Freelook', 'Klasik — Desenli Beyaz Kadran, Altın', '', 'Geometrik desenli beyaz kadran, altın indeksler ve altın bilezik. Her gün takılabilecek, sade ve ışıltılı bir model.', 5950.00, 'TRY', '/assets/images/watches/front/x-freelook-klasik-beyaz-altin.webp', 1)
