-- Generated by scripts/products-seed.mjs from src/lib/data/products.json. Do not edit by hand.
on conflict (slug) do update set
  name = excluded.name,
  brand = excluded.brand,
  model = excluded.model,
  reference = excluded.reference,
  description = excluded.description,
  price = excluded.price,
  currency = excluded.currency,
  image = excluded.image,
  stock = excluded.stock,
  is_active = true;

-- Watches no longer in the catalogue stay for old orders and favourites but leave the shop.
update public.products set is_active = false
 where slug not in ('casio-edifice-efb-730d-3av', 'casio-edifice-efr-s108de-3av', 'casio-mtp-e515d-2a2', 'casio-mtp-1374d-5av', 'casio-la680wga-4c', 'casio-a700w-1a', 'casio-f-91w-gumus-metal', 'casio-f-91ws-2', 'casio-ltp-v009g-7e', 'casio-ltp-1275sg-7b', 'daniel-klein-exclusive-siyah-deri', 'daniel-klein-yesil-kadran-bicolor', 'daniel-klein-exclusive-yesil-altin', 'daniel-klein-exclusive-pembe-kadran', 'daniel-klein-exclusive-siyah-celik', 'daniel-klein-gun-tarih-tirtikli', 'daniel-klein-exclusive-yesil-siyah', 'daniel-klein-exclusive-gumus-kadran', 'daniel-klein-exclusive-beyaz-cizgili', 'essence-kare-yesil-roma', 'essence-kare-sedef-tasli-bilezik', 'essence-sekizgen-sedef-zincir', 'essence-sedef-tasli-bicolor-rose', 'essence-multifonksiyon-altin', 'essence-yesil-kadran-tasli', 'essence-dikdortgen-sedef-bicolor', 'essence-mini-sedef-rose', 'freelook-baget-tasli-yesil', 'freelook-yesil-kadran-tasli', 'freelook-diamond-sedef', 'freelook-multifonksiyon-leopar', 'freelook-roma-rakamli-bicolor', 'freelook-kare-gumus-tasli', 'freelook-dikdortgen-beyaz-altin', 'freelook-klasik-beyaz-altin');
